L34_1 = "\236\185\180\235\165\180\235\169\152\236\157\180\235\161\156\234\181\176. \235\156\187\235\176\150\236\157\152 \235\172\180\237\155\136\236\157\132 \236\132\184\236\155\160\234\181\172\235\130\152, \236\139\156\235\172\180\235\165\180\234\183\184\236\157\152 \237\155\132\236\152\136\236\151\172."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "\227\130\171\227\131\171\227\131\161\227\131\179\227\129\139\227\128\130\230\137\139\230\159\132\227\129\160\227\129\170\227\128\129\227\130\183\227\131\160\227\131\171\227\130\176\227\129\174\229\190\140\231\182\153\232\128\133\227\130\136\227\128\130"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It is Carmen. This act of valor is of great service to me, Heir of Simurgh."
L33_1.m_Talk_ENG = L34_1
L34_1 = "\229\142\159\228\190\134\230\152\175\229\141\161\233\150\128\239\188\140\228\189\160\231\171\139\228\184\139\230\132\143\230\150\153\228\185\139\229\164\150\231\154\132\229\138\159\229\139\158\229\145\162\239\188\140\232\165\191\230\145\169\230\160\188\231\154\132\229\190\140\232\163\148\227\128\130"
L33_1.m_Talk_TWN = L34_1
L34_1 = "\224\184\161\224\184\177\224\184\153\224\184\132\224\184\183\224\184\173\224\184\132\224\184\178\224\184\163\224\185\140\224\185\128\224\184\161\224\184\153 \224\184\129\224\184\178\224\184\163\224\184\129\224\184\163\224\184\176\224\184\151\224\184\179\224\184\173\224\184\177\224\184\153\224\184\129\224\184\165\224\185\137\224\184\178\224\184\171\224\184\178\224\184\141\224\184\153\224\184\181\224\185\137\224\185\128\224\184\155\224\185\135\224\184\153\224\184\156\224\184\165\224\184\148\224\184\181\224\184\149\224\185\136\224\184\173\224\184\130\224\185\137\224\184\178\224\184\158\224\185\128\224\184\136\224\185\137\224\184\178 \224\184\156\224\184\185\224\185\137\224\184\170\224\184\183\224\184\154\224\185\128\224\184\138\224\184\183\224\185\137\224\184\173\224\184\170\224\184\178\224\184\162\224\184\161\224\184\178\224\184\136\224\184\178\224\184\129 Simurgh"
L33_1.m_Talk_THA = L34_1
