L6_1.m_fTalkTime = 0.03
L7_1 = "\227\129\167\227\129\153\227\129\140\226\128\166\226\128\166\227\129\147\227\129\174\227\129\190\227\129\190\227\129\167\227\129\175\230\173\187\227\129\172\227\129\190\227\129\167\227\131\141\227\130\173\227\131\134\227\130\163\227\130\162\227\129\171\230\128\175\227\129\136\227\129\166\230\154\174\227\130\137\227\129\153\227\129\147\227\129\168\227\129\171\227\129\170\227\130\139\227\129\139\227\130\130\227\129\151\227\130\140\227\129\170\227\129\132\227\130\147\227\129\167\227\129\153\227\128\130"
L6_1.m_Talk_JPN = L7_1
