L6_1.m_Talk_TWN = L7_1
L7_1 = "\224\185\129\224\184\149\224\185\136... \224\185\128\224\184\163\224\184\178\224\184\173\224\184\178\224\184\136\224\184\149\224\185\137\224\184\173\224\184\135\224\184\173\224\184\162\224\184\185\224\185\136\224\184\148\224\185\137\224\184\167\224\184\162\224\184\132\224\184\167\224\184\178\224\184\161\224\184\129\224\184\165\224\184\177\224\184\167\224\185\128\224\184\153\224\184\129\224\184\180\224\185\128\224\184\151\224\184\181\224\184\162\224\185\132\224\184\155\224\184\136\224\184\153\224\184\167\224\184\177\224\184\153\224\184\149\224\184\178\224\184\162"
